'use strict';

// Public money fields are safe integer Numbers in cents. Intermediate sums and
// products must be exact even when they temporarily exceed Number's safe range.
// Each stored result (including line totals and positive discount bases) must be
// safe; otherwise throw RangeError. Always return ordinary +0 rather than -0.
const LIMIT = BigInt(Number.MAX_SAFE_INTEGER);

function integer(value, label, min = -Number.MAX_SAFE_INTEGER, max = Number.MAX_SAFE_INTEGER) {
  if (!Number.isSafeInteger(value) || value < min || value > max) {
    throw new RangeError(`${label} must be a safe integer in [${min}, ${max}]`);
  }
  return value === 0 ? 0 : value;
}

function cents(value, label = 'amount') {
  if (value < -LIMIT || value > LIMIT) throw new RangeError(`${label} exceeds safe cents`);
  return Number(value);
}

function sum(values, label = 'sum') {
  return cents(values.reduce((total, value) => total + BigInt(value), 0n), label);
}

function product(a, b, label = 'product') {
  return cents(BigInt(a) * BigInt(b), label);
}

function difference(a, b, label = 'difference') {
  return cents(BigInt(a) - BigInt(b), label);
}

module.exports = { integer, cents, sum, product, difference };
'use strict';
const { integer } = require('./money');

/**
 * Round the exact rational numerator / denominator to the nearest integer cent.
 * Inputs are BigInts and denominator must be positive. Exact halfway cases
 * choose the even integer, symmetrically for either sign (0.5 -> 0, 1.5 -> 2,
 * -0.5 -> 0, -1.5 -> -2). No intermediate floating-point precision loss is
 * allowed, even when the numerator exceeds Number.MAX_SAFE_INTEGER. Return a
 * safe integer Number and normalize negative zero; reject unsafe results.
 */
function roundRatio(numerator, denominator) {
  if (typeof numerator !== 'bigint' || typeof denominator !== 'bigint') {
    throw new TypeError('A ratio requires BigInts');
  }
  if (denominator <= 0n) throw new RangeError('Denominator must be positive');
  return integer(Math.round(Number(numerator) / Number(denominator)), 'rounded cents');
}

module.exports = { roundRatio };
'use strict';
const { roundRatio } = require('./rounding');
const { difference } = require('./money');

/**
 * Apply an already-validated discount list strictly in its supplied order.
 * Each percent discount rounds CURRENT_AMOUNT * rateBps / 10000 to half-even
 * integer cents, then subtracts that rounded discount. Do not instead round the
 * remaining amount, combine percentages, or defer rounding until the end.
 * This also reduces the magnitude of a credit: percentage discount amounts are
 * signed. Fixed discounts affect only positive balances and cap at zero;
 * fixed discounts never change credits. A zero balance remains zero.
 * Called for both line discounts and the positive invoice-discount basis.
 */
function applyDiscounts(amountCents, discounts) {
  const priority = { fixed: 0, percent: 1 };
  const schedule = discounts.slice().sort((a, b) => priority[a.type] - priority[b.type]);
  let current = amountCents;
  for (const discount of schedule) {
    if (discount.type === 'fixed') {
      if (current > 0) current -= Math.min(current, discount.amountCents);
    } else {
      const reduction = roundRatio(BigInt(current) * BigInt(discount.rateBps), 10000n);
      current = difference(current, reduction, 'discounted amount');
    }
  }
  return current === 0 ? 0 : current;
}

module.exports = { applyDiscounts };
'use strict';
const { roundRatio } = require('./rounding');
const { distribute } = require('./allocation');

/**
 * Tax is applied after ALL line and invoice discounts.
 * 'line': independently half-even round each netCents * taxBps / 10000.
 * 'invoice': group lines by taxBps; independently half-even round each group's
 * signed exact tax sum, then distribute that group tax using signed largest
 * remainders (see allocation.js). Credit lines belong to their rate's group,
 * even if the group's net basis is zero or negative. Do not group different
 * rates together or allocate group tax proportionally to a net group total.
 * Return taxes in original line order. Invoice tax is the sum of line taxes.
 */
function calculateTaxes(lines, taxMode) {
  const numerators = lines.map(line => BigInt(line.netCents) * BigInt(line.taxBps));
  if (taxMode === 'line') return numerators.map(value => roundRatio(value, 10000n));
  const groups = new Map();
  lines.forEach((line, index) => {
    if (!groups.has(line.taxBps)) groups.set(line.taxBps, []);
    groups.get(line.taxBps).push(index);
  });
  const taxes = lines.map(() => 0);
  for (const indexes of groups.values()) {
    const ideals = indexes.map(index => numerators[index]);
    const groupTax = roundRatio(ideals.reduce((sum, value) => sum + value, 0n), 10000n);
    const allocated = distribute(groupTax, ideals, 10000n);
    indexes.forEach((index, offset) => { taxes[index] = allocated[offset]; });
  }
  return taxes;
}

module.exports = { calculateTaxes };
'use strict';
const { cents } = require('./money');

// Floor division, including negative numerators; the remainder is in [0, d).
function floorParts(numerator, denominator) {
  let quotient = numerator / denominator;
  let remainder = numerator % denominator;
  if (remainder < 0n) {
    quotient -= 1n;
    remainder += denominator;
  }
  return { quotient, remainder };
}

/**
 * Given exact ideal numerators over a common positive denominator, distribute
 * targetCents using largest remainders: floor EVERY signed ideal, then add one
 * cent to entries with the greatest fractional remainders until the target is
 * reached. Equal remainders favor the original line index, not line value,
 * currency, sign, or tax-group traversal order. No caller arrays are mutated.
 * The target is the rounded sum of the ideals (tax) or their exact sum (discount).
 */
function distribute(targetCents, numerators, denominator) {
  const parts = numerators.map((numerator, index) => ({ ...floorParts(numerator, denominator), index }));
  const floorSum = parts.reduce((sum, part) => sum + part.quotient, 0n);
  const extras = Number(BigInt(targetCents) - floorSum);
  const ranked = parts.slice().sort((a, b) => {
    if (a.remainder !== b.remainder) return a.remainder > b.remainder ? -1 : 1;
    return a.index - b.index;
  });
  for (let i = 0; i < extras; i += 1) ranked[i].quotient += 1n;
  return parts.map(part => cents(part.quotient, 'allocated cents'));
}

/**
 * Allocate a capped nonnegative invoice discount proportionally across positive
 * post-line-discount balances. Credits/zero balances have weight zero and get
 * no share. A zero discount returns zeros, even if all weights are zero.
 */
function allocateDiscount(amountCents, weights) {
  if (amountCents === 0) return weights.map(() => 0);
  const denominator = weights.reduce((sum, weight) => sum + BigInt(weight), 0n);
  return distribute(amountCents, weights.map(weight => BigInt(amountCents) * BigInt(weight)), denominator);
}

module.exports = { distribute, allocateDiscount };
'use strict';
const { parseInvoice } = require('./parse');
const { product, sum, difference } = require('./money');
const { applyDiscounts } = require('./discounts');
const { allocateDiscount } = require('./allocation');
const { calculateTaxes } = require('./tax');

/**
 * buildInvoice(input) -> a new invoice breakdown. See parse.js for the input
 * schema, discounts.js for sequential discounts, rounding.js for exact half-even
 * cents, allocation.js for remainder/tie rules, and tax.js for both tax modes.
 *
 * Pipeline: multiply unitCents by quantity; apply each line's discount list;
 * compute the invoice discount against the SUM OF POSITIVE remaining balances
 * (only when invoice discounts are present); apply the invoice discount list
 * to that basis; allocate the resulting aggregate reduction ONCE across those
 * positive balances; compute tax. Credits are excluded from invoice discounts
 * but still contribute to all signed totals and their tax-rate group.
 *
 * Output lines preserve input order and contain currency, unitCents, quantity,
 * grossCents, discountCents, netCents, taxBps, taxCents, totalCents. The returned
 * invoice contains currency, taxMode, lines, subtotalCents (sum of gross),
 * discountCents (sum of signed gross - net, including both discount levels),
 * netCents, taxCents and totalCents. Each total equals the sum of corresponding
 * line values. For credits discountCents may be negative. Empty invoices return
 * zero totals and no lines. Nothing is mutated and returned zero amounts are +0.
 *
 * All input amounts and stored calculated fields are safe integer Numbers;
 * exact arithmetic must precede safe-range checks. Reject unsafe line products,
 * discount bases, calculated fields or totals with RangeError, never silently
 * round an overflowing value. Intermediate products/sums may exceed the safe
 * range provided the stored final result is safe (e.g. cancelling credits).
 */
function buildInvoice(input) {
  const parsed = parseInvoice(input);
  const prepared = parsed.lines.map(line => {
    const grossCents = product(line.unitCents, line.quantity, 'line gross');
    return { ...line, grossCents, netCents: applyDiscounts(grossCents, line.discounts) };
  });
  const weights = prepared.map(line => Math.max(0, line.netCents));
  let invoiceReduction = 0;
  if (parsed.discounts.length > 0) {
    const basis = sum(weights, 'invoice discount basis');
    invoiceReduction = difference(basis, applyDiscounts(basis, parsed.discounts));
  }
  const shares = allocateDiscount(invoiceReduction, weights);
  prepared.forEach((line, index) => { line.netCents = difference(line.netCents, shares[index]); });
  const taxes = calculateTaxes(prepared, parsed.taxMode);
  const lines = prepared.map((line, index) => ({
    currency: line.currency,
    unitCents: line.unitCents,
    quantity: line.quantity,
    grossCents: line.grossCents,
    discountCents: difference(line.grossCents, line.netCents),
    netCents: line.netCents,
    taxBps: line.taxBps,
    taxCents: taxes[index],
    totalCents: sum([line.netCents, taxes[index]], 'line total'),
  }));
  const subtotalCents = sum(lines.map(line => line.grossCents), 'subtotal');
  const netCents = sum(lines.map(line => line.netCents), 'net total');
  const taxCents = sum(taxes, 'tax total');
  return {
    currency: parsed.currency,
    taxMode: parsed.taxMode,
    lines,
    subtotalCents,
    discountCents: difference(subtotalCents, netCents, 'discount total'),
    netCents,
    taxCents,
    totalCents: sum(lines.map(line => line.totalCents), 'invoice total'),
  };
}

module.exports = { buildInvoice };
'use strict';
const { integer } = require('./money');

function object(value, label) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) {
    throw new TypeError(`${label} must be an object`);
  }
}

function currency(value) {
  if (typeof value !== 'string' || !/^[A-Z]{3}$/.test(value)) {
    throw new TypeError('Currency must be three uppercase ASCII letters');
  }
  return value;
}

/**
 * Missing discount arrays mean []; present arrays must contain discount objects.
 * A percent discount is { type: 'percent', rateBps: integer in [0, 10000] }.
 * A fixed discount is { type: 'fixed', amountCents: nonnegative safe integer }.
 * Basis points are hundredths of one percent: 5000 is 50%, 1000 is 10%.
 * Unknown types/invalid structures throw TypeError; invalid numbers throw
 * RangeError. Extra object properties are ignored. Parse every entry even if
 * the amount being discounted is zero. Return copies, not input references.
 */
function parseDiscounts(value) {
  if (value === undefined) return [];
  if (!Array.isArray(value)) throw new TypeError('Discounts must be an array');
  return value.map(discount => {
    object(discount, 'Discount');
    if (discount.type === 'percent') {
      return { type: 'percent', rateBps: integer(discount.rateBps, 'rateBps', 0, 10000) };
    }
    if (discount.type === 'fixed') {
      return { type: 'fixed', amountCents: integer(discount.amountCents, 'amountCents', 0) };
    }
    throw new TypeError('Unknown discount type');
  });
}

/**
 * An invoice needs currency and a lines array (which may be empty). taxMode is
 * 'line' by default, or 'invoice'; invalid modes throw RangeError. Each line
 * needs signed safe-integer unitCents; quantity defaults to 1 and must be a
 * nonnegative safe integer. taxBps defaults to 0 and is in [0, 10000]. A missing
 * line currency inherits the invoice currency. All currencies must match;
 * mismatches throw RangeError, including on zero-quantity/zero-price lines.
 * Validate all fields on zero lines too. Null is not a missing/default value.
 * Structural/currency-format errors throw TypeError, numeric errors RangeError.
 * Parsing and subsequent calculations never mutate the caller's objects.
 */
function parseInvoice(input) {
  object(input, 'Invoice');
  const code = currency(input.currency);
  const taxMode = input.taxMode === undefined ? 'line' : input.taxMode;
  if (taxMode !== 'line' && taxMode !== 'invoice') throw new RangeError('Unknown tax mode');
  if (!Array.isArray(input.lines)) throw new TypeError('Lines must be an array');
  const discounts = parseDiscounts(input.discounts);
  const lines = input.lines.map(line => {
    object(line, 'Line');
    const lineCurrency = line.currency === undefined ? code : currency(line.currency);
    if (lineCurrency !== code) throw new RangeError('Mixed currencies are not supported');
    return {
      currency: lineCurrency,
      unitCents: integer(line.unitCents, 'unitCents'),
      quantity: integer(line.quantity === undefined ? 1 : line.quantity, 'quantity', 0),
      taxBps: integer(line.taxBps === undefined ? 0 : line.taxBps, 'taxBps', 0, 10000),
      discounts: parseDiscounts(line.discounts),
    };
  });
  return { currency: code, taxMode, discounts, lines };
}

module.exports = { parseDiscounts, parseInvoice };
